"""National Master Railway Timetables and Active Train Operations Database."""

from dataclasses import dataclass
from typing import List, Dict

@dataclass
class TimetableStop:
    station_code: str
    scheduled_arrival_min: int
    scheduled_departure_min: int
    platform_number: int
    dwell_time_min: int
    distance_km: float

@dataclass
class TrainScheduleRecord:
    train_number: str
    train_name: str
    category: str
    priority_rank: int
    max_speed_kmh: int
    operating_days: List[str]
    stops: List[TimetableStop]
    rake_type: str

